-- solution.sql — YOUR answer for: Exercise 1 — fix the SQL injection in a product search
-- Bài làm CỦA BẠN. Run order / thứ tự chạy: setup.sql → solution.sql → check.sql
USE DBI202_CL;
GO
CREATE OR ALTER PROCEDURE dbo.prTimSanPham @tuKhoa NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    -- VULNERABLE: the user's text becomes part of the SQL code
    DECLARE @sql NVARCHAR(MAX) = N'SELECT id, ten, gia FROM dbo.SanPham WHERE ten LIKE N''%' + @tuKhoa + N'%''';
    EXEC (@sql);
END

-- setup.sql — sample database for: Exercise 1 — fix the SQL injection in a product search
-- Drops and re-creates the database DBI202_CL (a scratch database used only by Code Lab exercises), then the tables + rows.
-- Xoá và tạo lại CSDL DBI202_CL (CSDL nháp chỉ dùng cho bài Code Lab), rồi tạo bảng + dữ liệu. Chạy lại bất cứ lúc nào để làm sạch.
USE master;
GO
IF DB_ID(N'DBI202_CL') IS NOT NULL
BEGIN
    ALTER DATABASE DBI202_CL SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE DBI202_CL;
END
GO
CREATE DATABASE DBI202_CL;
GO
USE DBI202_CL;
GO
CREATE TABLE dbo.SanPham (id INT NOT NULL PRIMARY KEY, ten NVARCHAR(50) NOT NULL, gia DECIMAL(12,0) NOT NULL);
INSERT INTO dbo.SanPham VALUES (1, N'Bút bi', 5000), (2, N'Vở kẻ ngang', 12000), (3, N'Thước kẻ', 8000);
GO
PRINT N'setup.sql: database DBI202_CL ready.';

-- check.sql — self-check for: Exercise 1 — fix the SQL injection in a product search
-- Generated with the exercise — DO NOT EDIT. Run it AFTER setup.sql and your solution.sql (see the task text).
-- Tự kiểm cho bài này — sinh kèm đề, ĐỪNG SỬA. Chạy SAU setup.sql và solution.sql của bạn (xem đề).
USE DBI202_CL;
GO
SET NOCOUNT ON;
DECLARE @ok BIT, @info NVARCHAR(4000), @pass INT = 0, @fail INT = 0;
PRINT N'────────── check.sql: 4 checks ──────────';

-- CHECK 1: A normal search for "kẻ" finds the two rulers/notebooks
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @r TABLE (id INT, ten NVARCHAR(50), gia DECIMAL(12,0)); DECLARE @e INT = 0;
BEGIN TRY INSERT INTO @r EXEC dbo.prTimSanPham N''kẻ''; END TRY BEGIN CATCH SET @e = ERROR_NUMBER(); END CATCH;
SET @ok = IIF(@e = 0 AND (SELECT COUNT(*) FROM @r) = 2 AND NOT EXISTS (SELECT 1 FROM @r WHERE id = 1), 1, 0);
SET @info = CONCAT(N''rows = '', (SELECT COUNT(*) FROM @r), N'', error = '', @e);',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 1. A normal search for "kẻ" finds the two rulers/notebooks | Tìm bình thường "kẻ" ra hai sản phẩm'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 1. A normal search for "kẻ" finds the two rulers/notebooks | Tìm bình thường "kẻ" ra hai sản phẩm', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 2: The UNION payload returns nothing and raises no error
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @r TABLE (id INT, ten NVARCHAR(50), gia DECIMAL(12,0)); DECLARE @e INT = 0;
BEGIN TRY INSERT INTO @r EXEC dbo.prTimSanPham N''x%'''' UNION SELECT id, ten, 1 FROM dbo.SanPham --''; END TRY BEGIN CATCH SET @e = ERROR_NUMBER(); END CATCH;
SET @ok = IIF(@e = 0 AND (SELECT COUNT(*) FROM @r) = 0, 1, 0);
SET @info = CONCAT(N''rows = '', (SELECT COUNT(*) FROM @r), N'' (fake prices: '', (SELECT COUNT(*) FROM @r WHERE gia = 1), N''), error = '', @e);',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 2. The UNION payload returns nothing and raises no error | Payload UNION không trả gì và không báo lỗi'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 2. The UNION payload returns nothing and raises no error | Payload UNION không trả gì và không báo lỗi', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 3: A DROP TABLE payload does nothing
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @t TABLE (x INT); BEGIN TRAN;
DECLARE @r TABLE (id INT, ten NVARCHAR(50), gia DECIMAL(12,0)); DECLARE @e INT = 0;
BEGIN TRY INSERT INTO @r EXEC dbo.prTimSanPham N''''''; DROP TABLE dbo.SanPham; --''; END TRY BEGIN CATCH SET @e = ERROR_NUMBER(); END CATCH;
SET @ok = IIF(OBJECT_ID(N''dbo.SanPham'') IS NOT NULL, 1, 0);
SET @info = IIF(@ok = 1, N''table still there'', N''dbo.SanPham was dropped!'');
IF @@TRANCOUNT > 0 ROLLBACK;',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 3. A DROP TABLE payload does nothing | Payload DROP TABLE không làm gì'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 3. A DROP TABLE payload does nothing | Payload DROP TABLE không làm gì', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 4: A product name with an apostrophe can be searched
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'BEGIN TRAN; INSERT INTO dbo.SanPham VALUES (4, N''Bút O''''Neil'', 9000);
DECLARE @r TABLE (id INT, ten NVARCHAR(50), gia DECIMAL(12,0)); DECLARE @e INT = 0;
BEGIN TRY INSERT INTO @r EXEC dbo.prTimSanPham N''O''''Neil''; END TRY BEGIN CATCH SET @e = ERROR_NUMBER(); END CATCH;
SET @ok = IIF(@e = 0 AND (SELECT COUNT(*) FROM @r) = 1, 1, 0);
SET @info = CONCAT(N''rows = '', (SELECT COUNT(*) FROM @r), N'', error = '', @e);
IF @@TRANCOUNT > 0 ROLLBACK;',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 4. A product name with an apostrophe can be searched | Tìm được tên có dấu nháy đơn'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 4. A product name with an apostrophe can be searched | Tìm được tên có dấu nháy đơn', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

PRINT N'──────────────────────────────────────';
IF @fail = 0 PRINT CONCAT(N'ALL ', @pass, N' CHECKS PASSED — go back to Code Lab and press "Mark as solved".');
ELSE PRINT CONCAT(@pass, N' passed, ', @fail, N' FAILED — fix solution.sql, then run setup.sql, solution.sql, check.sql again.');
SELECT CASE WHEN @fail = 0 THEN N'ALL CHECKS PASSED' ELSE N'NOT YET' END AS Result, @pass AS Passed, @fail AS Failed;
IF @fail > 0 RAISERROR(N'%d check(s) failed', 16, 1, @fail);

