-- solution.sql — YOUR answer for: Exercise 2 — a least-privilege account for the revenue report
-- Bài làm CỦA BẠN. Run order / thứ tự chạy: setup.sql → solution.sql → check.sql
USE DBI202_CL;
GO
-- CREATE ROLE rBaoCao; GRANT ... TO rBaoCao;
-- CREATE USER report_user WITHOUT LOGIN; ALTER ROLE rBaoCao ADD MEMBER report_user;

-- setup.sql — sample database for: Exercise 2 — a least-privilege account for the revenue report
-- Drops and re-creates the database DBI202_CL (a scratch database used only by Code Lab exercises), then the tables + rows.
-- Xoá và tạo lại CSDL DBI202_CL (CSDL nháp chỉ dùng cho bài Code Lab), rồi tạo bảng + dữ liệu. Chạy lại bất cứ lúc nào để làm sạch.
USE master;
GO
IF DB_ID(N'DBI202_CL') IS NOT NULL
BEGIN
    ALTER DATABASE DBI202_CL SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE DBI202_CL;
END
GO
CREATE DATABASE DBI202_CL;
GO
USE DBI202_CL;
GO
CREATE TABLE dbo.KhachHang (id INT NOT NULL PRIMARY KEY, ten NVARCHAR(50) NOT NULL);
CREATE TABLE dbo.DonHang (id INT NOT NULL PRIMARY KEY, khachHangId INT NOT NULL REFERENCES dbo.KhachHang (id), tongTien DECIMAL(12,0) NOT NULL);
CREATE TABLE dbo.NhanVien (id INT NOT NULL PRIMARY KEY, ten NVARCHAR(50) NOT NULL, luong DECIMAL(12,0) NOT NULL);
INSERT INTO dbo.KhachHang VALUES (1, N'An'), (2, N'Bình');
INSERT INTO dbo.DonHang VALUES (1, 1, 150000), (2, 2, 90000), (3, 1, 40000);
INSERT INTO dbo.NhanVien VALUES (1, N'Quang', 30000000), (2, N'Hà', 18000000);
GO
PRINT N'setup.sql: database DBI202_CL ready.';

-- check.sql — self-check for: Exercise 2 — a least-privilege account for the revenue report
-- Generated with the exercise — DO NOT EDIT. Run it AFTER setup.sql and your solution.sql (see the task text).
-- Tự kiểm cho bài này — sinh kèm đề, ĐỪNG SỬA. Chạy SAU setup.sql và solution.sql của bạn (xem đề).
USE DBI202_CL;
GO
SET NOCOUNT ON;
DECLARE @ok BIT, @info NVARCHAR(4000), @pass INT = 0, @fail INT = 0;
PRINT N'────────── check.sql: 4 checks ──────────';

-- CHECK 1: report_user can read DonHang joined with KhachHang
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @e INT = 0;
BEGIN TRY
    EXECUTE AS USER = N''report_user'';
    DECLARE @n INT = (SELECT COUNT(*) FROM dbo.DonHang d JOIN dbo.KhachHang k ON k.id = d.khachHangId);
    REVERT;
END TRY
BEGIN CATCH
    SET @e = ERROR_NUMBER();
    IF USER_NAME() = N''report_user'' REVERT;
END CATCH;
SET @ok = IIF(@e = 0 AND USER_ID(N''report_user'') IS NOT NULL, 1, 0);
SET @info = CONCAT(N''error = '', @e);',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 1. report_user can read DonHang joined with KhachHang | report_user đọc được DonHang nối KhachHang'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 1. report_user can read DonHang joined with KhachHang | report_user đọc được DonHang nối KhachHang', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 2: report_user cannot read NhanVien (error 229)
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @e INT = 0;
BEGIN TRY
    EXECUTE AS USER = N''report_user'';
    DECLARE @n INT = (SELECT COUNT(*) FROM dbo.NhanVien);
    REVERT;
END TRY
BEGIN CATCH
    SET @e = ERROR_NUMBER();
    IF USER_NAME() = N''report_user'' REVERT;
END CATCH;
SET @ok = IIF(@e = 229, 1, 0);
SET @info = CONCAT(N''error = '', @e, IIF(@e = 0, N'' — the salaries are readable!'', N''''));',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 2. report_user cannot read NhanVien (error 229) | report_user không đọc được NhanVien (lỗi 229)'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 2. report_user cannot read NhanVien (error 229) | report_user không đọc được NhanVien (lỗi 229)', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 3: report_user cannot change orders (INSERT, UPDATE, DELETE refused)
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @bad INT = 0;
BEGIN TRAN;
BEGIN TRY EXECUTE AS USER = N''report_user''; UPDATE dbo.DonHang SET tongTien = 0; REVERT; SET @bad += 1; END TRY BEGIN CATCH IF USER_NAME() = N''report_user'' REVERT; IF ERROR_NUMBER() <> 229 SET @bad += 10; END CATCH;
BEGIN TRY EXECUTE AS USER = N''report_user''; INSERT INTO dbo.DonHang VALUES (9, 1, 1); REVERT; SET @bad += 1; END TRY BEGIN CATCH IF USER_NAME() = N''report_user'' REVERT; IF ERROR_NUMBER() <> 229 SET @bad += 10; END CATCH;
BEGIN TRY EXECUTE AS USER = N''report_user''; DELETE FROM dbo.DonHang; REVERT; SET @bad += 1; END TRY BEGIN CATCH IF USER_NAME() = N''report_user'' REVERT; IF ERROR_NUMBER() <> 229 SET @bad += 10; END CATCH;
IF @@TRANCOUNT > 0 ROLLBACK;
SET @ok = IIF(@bad = 0, 1, 0);
SET @info = CONCAT(N''writes that went through: '', @bad % 10, N'' · other errors: '', @bad / 10);',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 3. report_user cannot change orders (INSERT, UPDATE, DELETE refused) | report_user không sửa được đơn (INSERT, UPDATE, DELETE bị từ chối)'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 3. report_user cannot change orders (INSERT, UPDATE, DELETE refused) | report_user không sửa được đơn (INSERT, UPDATE, DELETE bị từ chối)', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 4: The permissions belong to rBaoCao, and report_user is in no other role
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'SET @ok = IIF(EXISTS (SELECT 1 FROM sys.database_permissions p WHERE p.grantee_principal_id = DATABASE_PRINCIPAL_ID(N''rBaoCao'') AND p.permission_name = ''SELECT'' AND p.major_id = OBJECT_ID(N''dbo.DonHang''))
  AND NOT EXISTS (SELECT 1 FROM sys.database_permissions p WHERE p.grantee_principal_id = DATABASE_PRINCIPAL_ID(N''report_user'') AND p.class = 1)
  AND (SELECT COUNT(*) FROM sys.database_role_members m WHERE m.member_principal_id = DATABASE_PRINCIPAL_ID(N''report_user'')) = 1
  AND EXISTS (SELECT 1 FROM sys.database_role_members m WHERE m.member_principal_id = DATABASE_PRINCIPAL_ID(N''report_user'') AND m.role_principal_id = DATABASE_PRINCIPAL_ID(N''rBaoCao'')), 1, 0);
SET @info = CONCAT(N''roles of report_user: '', (SELECT STRING_AGG(USER_NAME(m.role_principal_id), '', '') FROM sys.database_role_members m WHERE m.member_principal_id = DATABASE_PRINCIPAL_ID(N''report_user'')));',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
